 1	method MinSecondValueFirst(s: array<seq<int>>) returns (firstOfMinSecond: int)
 2	    requires s.Length > 0
 3	    requires forall i :: 0 <= i < s.Length ==> |s[i]| >= 2
 4	    ensures exists i :: 0 <= i < s.Length && firstOfMinSecond == s[i][0] && 
 5	        (forall j :: 0 <= j < s.Length ==> s[i][1] <= s[j][1])
 6	{
 7	    var minSecondIndex := 0;
 8	    for i := 1 to s.Length
 9	        invariant 0 <= i <= s.Length
10	        invariant forall j :: 0 <= j < i ==> s[minSecondIndex][1] <= s[j][1]
11	    {
12	        if s[i][1] < s[minSecondIndex][1]
13	        {
14	            minSecondIndex := i;
15	        }
16	    }
17	    firstOfMinSecond := s[minSecondIndex][0];
18	}

